# shellcheck shell=bash
# test-slots.sh — sourced by the router smoke scripts: the live test model slots, read from the
# repo-root test-slots.json (the same file scripts/lib/test-slots.mjs reads); TEST_SLOT_<NAME>
# overrides one slot for one run. Defines functions only; sourcing has no side effect.

# >>> shguard modes=source (generated by shell-disposition-gate --guard; do not edit)
case $(realpath -- "$0" 2>/dev/null) in */'scripts/lib/test-slots.sh') _shguard_m='exec' ;; *) if [ "${SHGUARD_MODE-}" = 'pipe' ]; then _shguard_m='pipe'; else _shguard_m='source'; fi ;; esac
# shellcheck disable=SC2317
case $_shguard_m in
  source) unset _shguard_m ;;
  *) printf '%s: refusing %s invocation (supports: source; pipe callers set SHGUARD_MODE=pipe)\n' 'test-slots.sh' "$_shguard_m" >&2; unset _shguard_m; return 1 2>/dev/null || exit 1 ;;
esac
# <<< shguard
test_slot() { # <NAME>; prints the slot value; non-zero (stderr names the slot and source) when unusable
	local name="${1:-}" file val src ovr known ok k
	file="$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../../test-slots.json"
	# The known slot names are the keys of the file minus the `_`-prefixed ones (`_comment`);
	# every slot value is a bare id (no "/") except OPENROUTER_ADD_PROBE, an @preset/<slug> id.
	ovr="TEST_SLOT_${name}"
	case "$name" in
	'' | *[!A-Za-z0-9_]*) val="" ;; # not a variable-name suffix: no override to read
	*) val="${!ovr:-}" ;;
	esac
	if known=$(jq -er 'keys_unsorted | map(select(startswith("_") | not)) | join(" ")' "$file" 2>/dev/null); then
		ok=
		for k in $known; do if [ "$k" = "$name" ]; then ok=1; fi; done
		if [ -z "$ok" ]; then
			echo "test-slots: unknown slot '${name}' (known: ${known})" >&2
			return 1
		fi
	elif [ -z "$val" ]; then
		echo "test-slots: slot ${name} is unreadable: the file is missing or not a JSON object (${file})" >&2
		return 1
	fi
	src="the ${ovr} override"
	if [ -z "$val" ]; then
		src=$file
		if ! val=$(jq -er --arg n "$name" 'if (.[$n] | type) == "string" then .[$n] else empty end' "$file" 2>/dev/null); then
			echo "test-slots: slot ${name} is missing, empty or not a string, or the file is unreadable (${src})" >&2
			return 1
		fi
	fi
	if [ -z "$val" ]; then
		echo "test-slots: slot ${name} is empty (${src})" >&2
		return 1
	fi
	case "$val" in
	*/*)
		if [ "$name" != OPENROUTER_ADD_PROBE ]; then
			echo "test-slots: slot ${name} must be a bare id without a '/', got '${val}' (${src})" >&2
			return 1
		fi
		;;
	esac
	printf '%s\n' "$val"
}

codex_test_persona() { # <model-ids, newline separated>; prints the codex persona; non-zero when none is named
	local persona="${CODEX_TEST_PERSONA:-}"
	[ -n "$persona" ] || persona=$(printf '%s\n' "${1:-}" | sed -n 's|^\(codex-[^/]*\)/.*|\1|p' | head -n1)
	if [ -z "$persona" ]; then
		echo "test-slots: no codex persona: set \$CODEX_TEST_PERSONA (or list a codex-* provider in /v1/models)" >&2
		return 1
	fi
	printf '%s\n' "$persona"
}

slot_not_served() { # <NAME> <value>; the one "not served" message; the caller then fails the leg
	echo "slot ${1}=${2} is not served — edit test-slots.json" >&2
}
